<?php
namespace App\Helpers;use App\Core\DB;
class AdminAuth {const KEY='vp_admin';public static function ensure(DB $db):void{$db->query("CREATE TABLE IF NOT EXISTS vp_admin_users(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,name VARCHAR(150) NOT NULL,role ENUM('admin','cs','production') NOT NULL DEFAULT 'cs',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY vp_admin_users_email_unique(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}public static function user():?array{$u=$_SESSION[self::KEY]??null;return is_array($u)?$u:null;}public static function login(array $u):void{session_regenerate_id(true);$_SESSION[self::KEY]=['id'=>(int)$u['id'],'email'=>$u['email'],'name'=>$u['name'],'role'=>$u['role']];}public static function logout():void{unset($_SESSION[self::KEY]);session_regenerate_id(true);}}
